Given an array arr[] and a target value, the task is to find the count of triplets present in the given array having sum equal to the given target. Examples:Input: arr[] = [0, -1, 2, -3, 1], target = -2Output: 2Explanation: Two triplets that add up to -2 are:arr[0] + arr[3] + arr[4] = 0 + (-3) + (1) = -2arr[1] + arr[2] + arr[3] = (-1) + 2 + (-3) = -2Input: arr[] = [1, -2, 1, 0, 5], target = 1Output: 0Explanation: There is no triplet whose sum is equal to 1. Table of Content[Naive Approach] Explore all Triplets – O(n^3) Time and O(1) Space[Expected Approach 1] Using Hash Set - O(n^2) Time and O(n) Space[Naive Approach] Explore all Triplets – O(n^3) Time and O(1) SpaceThe naive approach is to explore all the triplets using three nested loops and if the sum of any triplet is equal to given target then increment the counter by 1.
            C++

    // C++ program to count all triplets having sum equal to
// target by exploring all possible triplets

#include <iostream>
#include <vector>
using namespace std;

int countTriplets(vector<int> &arr, int target) {
    int cnt = 0;
    int n = arr.size();

    // Generating all triplets
    for (int i = 0; i < n - 2; i++) {
        for (int j = i + 1; j < n - 1; j++) {
            for (int k = j + 1; k < n; k++) {

                // If the sum of a triplet is equal to target
                // then increment count by 1
                if (arr[i] + arr[j] + arr[k] == target)
                    cnt += 1;
            }
        }
    }
    return cnt;
}

int main() {
    vector<int> arr = {0, -1, 2, -3, 1};
    int target = -2;

    cout << countTriplets(arr, target);
    return 0;
}


