    // Returns number of pairs in arr[idx..n-1] with sum equal
    // to 'target'
    static int getPairsCount(int[] arr, int idx, int target) {
        Map<Integer, Integer> freq = new HashMap<>();
        int count = 0;

        for (int i = idx; i < arr.length; i++) {

            // Check if the complement (target - arr[i])
            // exists in the map. If yes, increment count
            if (freq.containsKey(target - arr[i])) {
                count += freq.get(target - arr[i]);
            }

            // Increment the frequency of arr[i]
            freq.put(arr[i], freq.getOrDefault(arr[i], 0) + 1);
        }
        return count;
    }

    // Returns count of triplets with sum = target
    static int countTriplets(int[] arr, int target) {
        int cnt = 0;
        int n = arr.length;

        // Iterating over the first element of the triplet
        for (int i = 0; i < n - 2; i++) {
            int rem = target - arr[i];
            cnt += getPairsCount(arr, i + 1, rem);
        }
        return cnt;
    }

    public static void main(String[] args) {
        int[] arr = {0, -1, 2, -3, 1};
        int target = -2;

        System.out.println(countTriplets(arr, target));
    }
}


